/* Types */
export type AccountChanged = null;

export type AccountStatus = { state: "signedOut" } | { state: "signedIn"; name: string; email: string | null };

export type ActiveSessionView = {
	session: Session,
	workstreamTitle: string,
	projectPath: string,
};

export type AddReviewCommentRequest = {
	workstreamId: string,
	path: string,
	side: ReviewSide,
	line: number,
	anchorText: string,
	body: string,
	parentId: string | null,
	/**  Answers an agent note and resolves it; the note's location replaces the request's. */
	replyToNoteId?: string | null,
};

export type AgentBundleInstall = {
	ok: boolean,
	exitCode: number | null,
	source: BundleSource,
	stdout: string,
	stderr: string,
	resolved?: CollisionReport | null,
};

export type AgentBundleReport = {
	source: BundleSource,
	stdout: string,
};

export type AgentBundleStatus = {
	manageable: boolean,
	installedSha: string | null,
	latestSha: string | null,
	installedVersion: string | null,
	desiredVersion: string | null,
	lastChecked: number | null,
	updateAvailable: boolean,
};

